package driver

import (
	"math"
	"time"
)

const (
	farePerMinute = 1.50
	minimumFare   = 3.50
)

// ComputeFare returns the fare in dollars for a route with the given ETA:
// $1.50 per minute, with a minimum of $3.50, rounded to the cent.
func ComputeFare(eta time.Duration) float64 {
	fare := eta.Minutes() * farePerMinute
	if fare < minimumFare {
		fare = minimumFare
	}
	return math.Round(fare*100) / 100
}

