func (d *database) exec(query string, args ...interface{}) (sql.Result, error) {
	res, err := d.db.Exec(query, args...)
	if err != nil && d.shouldRetry(err) {
		res, err = d.db.Exec(query, args...)
	}
	return res, err
}

