// number of rides.
func (d *database) ListRides(ctx context.Context) (*RideHistory, error) {
	d.logger.For(ctx).Info("Loading ride history")

	query := fmt.Sprintf("SELECT id, pickup_location, dropoff_location, request_time, "+
		"driver_plate, fare FROM ride_history ORDER BY request_time DESC, id DESC LIMIT %d", maxRideHistory)
	span := d.startSpan(ctx, query)
	defer span.End()

